package dev.pedro.learning.ecommerce.payment.provider;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;@Path("/admin/payment-provider")@Produces(MediaType.APPLICATION_JSON)public class PaymentProviderAdminResource{private final FakePaymentProviderState state;private final PaymentProviderGateway gateway;public PaymentProviderAdminResource(FakePaymentProviderState state,PaymentProviderGateway gateway){this.state=state;this.gateway=gateway;}@PUT @Path("/mode/{mode}")public PaymentProviderStats mode(@PathParam("mode")PaymentProviderMode mode){state.configureMode(mode);return stats();}@PUT @Path("/fail-first/{count}")public PaymentProviderStats failFirst(@PathParam("count")int count){state.failFirstN(count);state.configureMode(PaymentProviderMode.FAIL_FIRST_N_ATTEMPTS);return stats();}@PUT @Path("/delay/{millis}")public PaymentProviderStats delay(@PathParam("millis")long millis){state.delayMs(millis);return stats();}@PUT @Path("/failure-percentage/{percentage}")public PaymentProviderStats percentage(@PathParam("percentage")int percentage){state.failurePercentage(percentage);state.configureMode(PaymentProviderMode.FAIL_PERCENTAGE);return stats();}@PUT @Path("/reset")public PaymentProviderStats reset(){state.reset();gateway.resetStats();return stats();}@GET @Path("/stats")public PaymentProviderStats stats(){return new PaymentProviderStats(state.mode(),state.calls(),state.successes(),state.failures(),gateway.fallbackCount(),state.failFirstN(),state.delayMs(),state.failurePercentage());}}